{
  "status": "STABLE",
  "core_findings": [
    "Training positives outrank sampled negatives at most observed positions in every dataset; negative-margin rates range from 0.79% to 7.67%, with no nonfinite margins observed.",
    "Electronics has the weakest training separation and the most aligned sampled embedding directions: its margin p10 is 0.3256 and embedding alignment score is 0.702. These measures do not establish validation ranking quality or recommendation diversity."
  ],
  "key_implications": [
    "Positive-versus-negative separation is already working across all four datasets, though Electronics has more low-margin positions.",
    "Electronics embeddings are more directionally aligned than those in the other datasets; this alone does not establish harmful representation collapse.",
    "The supplied training diagnostics cannot establish macro validation HR@10 or generalization."
  ],
  "evidence": {
    "headline_metrics": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": 0.0079,
      "Electronics:pos_neg_neg_beats_pos_rate": 0.0767,
      "Electronics:pos_neg_margin_p10": 0.3256,
      "Electronics:pos_neg_small_margin_rate": 0.1142,
      "Electronics:embedding_collapse_score": 0.702
    },
    "brief_metric_read": {
      "Movies_and_TV:pos_neg_neg_beats_pos_rate": "Lowest observed training ranking-error rate.",
      "Electronics:pos_neg_neg_beats_pos_rate": "Highest observed training ranking-error rate.",
      "Electronics:pos_neg_margin_p10": "Weakest lower-tail training separation.",
      "Electronics:pos_neg_small_margin_rate": "11.42% of finite training margins fall below 0.5.",
      "Electronics:embedding_collapse_score": "Highest sampled embedding directional alignment."
    }
  }
}
